/**
 * @module paper-viz/html-generator
 * @description 生成自包含的论文演示 HTML 文件
 *
 * 特性：
 * - 学术深色主题，CSS 变量，clamp() 响应式排版
 * - 100vh/100dvh 全屏幻灯片，overflow:hidden
 * - 键盘(←→/空格)、触摸滑动、鼠标滚轮导航
 * - contenteditable + localStorage 自动保存 + E 键切换
 * - Intersection Observer + reveal 动画
 * - 论文原文可点击链接
 * - 嵌入图表（base64 或相对路径）
 */

import type { PresentationData, PresentationSlide, ContentBlock, PresentationTheme } from './types';

/**
 * 生成论文演示 HTML
 * @param data - 演示文稿数据
 * @returns 完整的 HTML 字符串
 */
export function generatePaperHtml(data: PresentationData): string {
  const { theme } = data;
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(data.title)}</title>
<style>
${generateCSS(theme)}
</style>
</head>
<body>
<div class="presentation" id="presentation">
${data.slides.map((s, i) => renderSlide(s, i, data)).join('\n')}
</div>
<nav class="nav-dots" id="navDots" aria-label="Slide navigation">
${data.slides.map((s, i) => `<button class="dot${i === 0 ? ' active' : ''}" data-index="${i}" aria-label="Slide ${i + 1}">${i + 1}</button>`).join('\n')}
</nav>
<div class="slide-counter" id="slideCounter">1 / ${data.slides.length}</div>
<div class="edit-indicator" id="editIndicator">EDIT MODE</div>
<div class="controls-hint" id="controlsHint">
  <span>← → Space</span> Navigate
  <span>E</span> Edit mode
  <span>Scroll</span> Next/Prev
</div>
<script>
${generateJS(data)}
</script>
</body>
</html>`;
}

/** 生成完整 CSS */
function generateCSS(t: PresentationTheme): string {
  return `
:root {
  --primary: ${t.primaryColor};
  --accent: ${t.accentColor};
  --bg: ${t.backgroundColor};
  --surface: ${t.surfaceColor};
  --text: ${t.textColor};
  --text-secondary: ${t.textSecondaryColor};
  --code-bg: ${t.codeBackground};
  --font: ${t.fontFamily};
  --font-heading: ${t.headingFontFamily};
  --radius: 12px;
  --slide-gap: 0px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-snap-type: y mandatory;
  overflow-y: scroll;
  scroll-behavior: smooth;
  scrollbar-width: none;
}
html::-webkit-scrollbar { display: none; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* === Slide === */
.slide {
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(2rem, 5vw, 4rem) clamp(2rem, 8vw, 8rem);
  scroll-snap-align: start;
  position: relative;
  overflow: hidden;
}

.slide.layout-center {
  align-items: center;
  text-align: center;
}

.slide.layout-two-column .slide-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  width: 100%;
}

.slide.layout-full-image {
  padding: 2rem;
}
.slide.layout-full-image .block-image {
  max-height: 70vh;
}

/* === Slide Title === */
.slide-title {
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 3.5vw, 2.8rem);
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 1.5rem;
  line-height: 1.2;
}

.slide.layout-center .slide-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
}

/* === Content Blocks === */
.slide-content {
  max-width: 1100px;
  width: 100%;
}

.block { margin-bottom: 1.2rem; }

.block-heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  color: var(--text);
  line-height: 1.15;
  margin-bottom: 0.5rem;
}

.block-text {
  font-size: clamp(1rem, 1.8vw, 1.25rem);
  color: var(--text-secondary);
  line-height: 1.8;
}
.block-text.authors {
  font-size: clamp(1rem, 2vw, 1.35rem);
  color: var(--accent);
  margin-top: 1rem;
}
.block-text.meta {
  font-size: clamp(0.85rem, 1.4vw, 1.05rem);
  color: var(--text-secondary);
  margin-top: 0.5rem;
}
.block-text.summary {
  font-size: clamp(1.05rem, 1.9vw, 1.3rem);
  color: var(--text);
  border-left: 3px solid var(--primary);
  padding-left: 1rem;
}

.block-quote {
  border-left: 4px solid var(--accent);
  padding: 1rem 1.5rem;
  background: var(--surface);
  border-radius: 0 var(--radius) var(--radius) 0;
  font-style: italic;
  color: var(--text-secondary);
  font-size: clamp(0.9rem, 1.5vw, 1.1rem);
  line-height: 1.7;
}

.block-list-title {
  font-weight: 600;
  font-size: clamp(0.95rem, 1.6vw, 1.15rem);
  color: var(--primary);
  margin-bottom: 0.4rem;
}

.block-list {
  list-style: none;
  padding: 0;
}
.block-list li {
  position: relative;
  padding: 0.5rem 0 0.5rem 1.5rem;
  font-size: clamp(0.9rem, 1.5vw, 1.1rem);
  color: var(--text-secondary);
  border-bottom: 1px solid rgba(255,255,255,0.04);
}
.block-list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--primary);
}
.block-list li.sub-item {
  padding-left: 2.5rem;
  font-size: clamp(0.8rem, 1.3vw, 0.95rem);
  color: var(--text-secondary);
  opacity: 0.85;
}
.block-list li.sub-item::before {
  left: 1rem;
  width: 4px;
  height: 4px;
  background: var(--accent);
}

/* Importance badges */
.badge {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-right: 0.5rem;
  vertical-align: middle;
}
.badge-critical, .badge-major, .badge-high { background: #EF4444; color: #fff; }
.badge-important, .badge-moderate, .badge-medium { background: #F59E0B; color: #1a1a1a; }
.badge-supporting, .badge-minor, .badge-low { background: #6B7280; color: #fff; }

/* Keywords tags */
.keywords-container {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
  margin-top: 0.75rem;
}
.keyword-tag {
  padding: 0.25rem 0.75rem;
  background: var(--surface);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 20px;
  font-size: 0.85rem;
  color: var(--text-secondary);
}

/* === Images === */
.block-image {
  max-width: 100%;
  max-height: 55vh;
  object-fit: contain;
  border-radius: var(--radius);
  margin: 0.5rem auto;
  display: block;
}
.block-image-caption {
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 0.5rem;
  font-style: italic;
}

/* === Navigation Dots === */
.nav-dots {
  position: fixed;
  right: 1.5rem;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  z-index: 100;
}
.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--text-secondary);
  background: transparent;
  cursor: pointer;
  font-size: 0;
  transition: all 0.3s;
  padding: 0;
}
.dot.active {
  background: var(--primary);
  border-color: var(--primary);
  transform: scale(1.3);
}
.dot:hover {
  border-color: var(--primary);
}

/* === Slide Counter === */
.slide-counter {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  font-size: 0.85rem;
  color: var(--text-secondary);
  opacity: 0.6;
  z-index: 100;
  font-variant-numeric: tabular-nums;
}

/* === Edit Mode === */
.edit-indicator {
  position: fixed;
  top: 1rem;
  right: 1rem;
  padding: 0.3rem 0.8rem;
  background: var(--accent);
  color: #1a1a1a;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  opacity: 0;
  transition: opacity 0.3s;
  z-index: 100;
  pointer-events: none;
}
body.editing .edit-indicator { opacity: 1; }
body.editing [contenteditable="true"] {
  outline: 1px dashed var(--accent);
  outline-offset: 4px;
}

/* === Controls Hint === */
.controls-hint {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 1.5rem;
  font-size: 0.75rem;
  color: var(--text-secondary);
  opacity: 0.5;
  z-index: 100;
  transition: opacity 0.5s;
}
.controls-hint span {
  background: var(--surface);
  padding: 0.15rem 0.5rem;
  border-radius: 4px;
  font-family: monospace;
  margin-right: 0.3rem;
}

/* === Paper Link === */
.paper-link {
  display: inline-block;
  margin-top: 1rem;
  padding: 0.4rem 1rem;
  background: var(--surface);
  color: var(--primary);
  text-decoration: none;
  border-radius: var(--radius);
  border: 1px solid rgba(96,165,250,0.3);
  font-size: 0.9rem;
  transition: all 0.2s;
}
.paper-link:hover {
  background: var(--primary);
  color: var(--bg);
}

/* === Reveal Animations === */
.reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}
.reveal.scale {
  transform: scale(0.95);
}
.reveal.scale.visible {
  transform: scale(1);
}

/* === Responsive === */
@media (max-width: 768px) {
  .slide { padding: 1.5rem; }
  .slide.layout-two-column .slide-content {
    grid-template-columns: 1fr;
  }
  .nav-dots { right: 0.5rem; }
  .controls-hint { display: none; }
}

@media print {
  html { scroll-snap-type: none; }
  .slide { min-height: auto; page-break-after: always; padding: 2rem; }
  .nav-dots, .slide-counter, .edit-indicator, .controls-hint { display: none; }
}
`;
}

/** 渲染单张幻灯片 */
function renderSlide(slide: PresentationSlide, index: number, data: PresentationData): string {
  const layoutClass = slide.layout ? ` layout-${slide.layout}` : ' layout-default';
  const isTitle = slide.type === 'title';

  let html = `<section class="slide${layoutClass}" id="slide-${index}" data-type="${slide.type}">`;

  if (!isTitle) {
    html += `<h2 class="slide-title reveal">${escapeHtml(slide.title)}</h2>`;
  }

  html += `<div class="slide-content">`;

  for (const block of slide.blocks) {
    html += renderBlock(block);
  }

  // 标题页添加论文链接
  if (isTitle && data.url) {
    html += `<a class="paper-link reveal" href="${escapeHtml(data.url)}" target="_blank" rel="noopener">View Original Paper ↗</a>`;
  }

  html += `</div>`;
  html += `</section>`;

  return html;
}

/** 渲染内容块 */
function renderBlock(block: ContentBlock): string {
  const cls = block.className ? ` ${block.className}` : '';

  switch (block.type) {
    case 'heading':
      return `<div class="block reveal"><h1 class="block-heading${cls}" contenteditable="false">${escapeHtml(block.content)}</h1></div>`;

    case 'text': {
      // 支持简单的 **bold** 标记
      const content = escapeHtml(block.content).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
      return `<div class="block reveal"><p class="block-text${cls}" contenteditable="false">${content}</p></div>`;
    }

    case 'quote':
      return `<div class="block reveal"><blockquote class="block-quote${cls}" contenteditable="false">${escapeHtml(block.content)}</blockquote></div>`;

    case 'list': {
      const variant = block.variant;
      const badgeHtml = variant
        ? `<span class="badge badge-${variant}">${variant}</span>`
        : '';
      let html = `<div class="block reveal">`;
      if (block.content) {
        html += `<div class="block-list-title">${badgeHtml}${escapeHtml(block.content)}</div>`;
      }
      if (block.className === 'keywords') {
        // Keywords 使用标签样式
        html += `<div class="keywords-container">`;
        for (const item of block.items ?? []) {
          html += `<span class="keyword-tag">${escapeHtml(item)}</span>`;
        }
        html += `</div>`;
      } else {
        html += `<ul class="block-list" contenteditable="false">`;
        if (block.items) {
          for (const item of block.items) {
            html += `<li class="sub-item">${escapeHtml(item)}</li>`;
          }
        }
        html += `</ul>`;
      }
      html += `</div>`;
      return html;
    }

    case 'image':
      return `<div class="block reveal scale">
<img class="block-image" src="${escapeHtml(block.src ?? '')}" alt="${escapeHtml(block.content)}" loading="lazy">
${block.caption ? `<p class="block-image-caption">${escapeHtml(block.caption)}</p>` : ''}
</div>`;

    case 'badge':
      return `<div class="block reveal"><span class="badge badge-${block.variant ?? 'supporting'}">${escapeHtml(block.content)}</span></div>`;

    default:
      return `<div class="block reveal"><p class="block-text">${escapeHtml(block.content)}</p></div>`;
  }
}

/** 生成交互 JS */
function generateJS(data: PresentationData): string {
  return `
(function() {
  'use strict';

  const TOTAL = ${data.slides.length};
  const STORAGE_KEY = 'paper-viz-edits-' + ${escapeJsString(data.title.slice(0, 40))};
  let current = 0;
  let editing = false;
  let touchStartY = 0;
  let scrollLock = false;

  const slides = document.querySelectorAll('.slide');
  const dots = document.querySelectorAll('.dot');
  const counter = document.getElementById('slideCounter');
  const hint = document.getElementById('controlsHint');

  // === Navigation ===
  function goTo(index) {
    if (index < 0 || index >= TOTAL) return;
    current = index;
    slides[current].scrollIntoView({ behavior: 'smooth' });
    updateUI();
  }

  function next() { goTo(current + 1); }
  function prev() { goTo(current - 1); }

  function updateUI() {
    dots.forEach(function(d, i) {
      d.classList.toggle('active', i === current);
    });
    counter.textContent = (current + 1) + ' / ' + TOTAL;
  }

  // Keyboard
  document.addEventListener('keydown', function(e) {
    if (editing) return;
    switch (e.key) {
      case 'ArrowRight': case 'ArrowDown': case ' ':
        e.preventDefault(); next(); break;
      case 'ArrowLeft': case 'ArrowUp':
        e.preventDefault(); prev(); break;
      case 'Home': e.preventDefault(); goTo(0); break;
      case 'End': e.preventDefault(); goTo(TOTAL - 1); break;
      case 'e': case 'E':
        toggleEdit(); break;
    }
  });

  // Scroll / Wheel
  document.addEventListener('wheel', function(e) {
    if (editing || scrollLock) return;
    scrollLock = true;
    if (e.deltaY > 30) next();
    else if (e.deltaY < -30) prev();
    setTimeout(function() { scrollLock = false; }, 800);
  }, { passive: true });

  // Touch
  document.addEventListener('touchstart', function(e) {
    touchStartY = e.touches[0].clientY;
  }, { passive: true });
  document.addEventListener('touchend', function(e) {
    if (editing) return;
    var diff = touchStartY - e.changedTouches[0].clientY;
    if (Math.abs(diff) > 50) {
      if (diff > 0) next(); else prev();
    }
  }, { passive: true });

  // Navigation dots
  dots.forEach(function(dot) {
    dot.addEventListener('click', function() {
      goTo(parseInt(this.dataset.index));
    });
  });

  // Intersection Observer for current slide tracking and reveal
  var observer = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting) {
        var idx = Array.from(slides).indexOf(entry.target);
        if (idx !== -1) {
          current = idx;
          updateUI();
        }
        // Reveal animations
        entry.target.querySelectorAll('.reveal').forEach(function(el) {
          el.classList.add('visible');
        });
      }
    });
  }, { threshold: 0.5 });

  slides.forEach(function(s) { observer.observe(s); });

  // === Edit Mode ===
  function toggleEdit() {
    editing = !editing;
    document.body.classList.toggle('editing', editing);
    var editableEls = document.querySelectorAll('[contenteditable]');
    editableEls.forEach(function(el) {
      el.contentEditable = editing ? 'true' : 'false';
    });
    if (!editing) saveEdits();
  }

  function saveEdits() {
    try {
      var edits = {};
      slides.forEach(function(slide, i) {
        var editableEls = slide.querySelectorAll('[contenteditable]');
        editableEls.forEach(function(el, j) {
          var key = i + '-' + j;
          edits[key] = el.innerHTML;
        });
      });
      localStorage.setItem(STORAGE_KEY, JSON.stringify(edits));
    } catch(e) {}
  }

  function loadEdits() {
    try {
      var saved = localStorage.getItem(STORAGE_KEY);
      if (!saved) return;
      var edits = JSON.parse(saved);
      slides.forEach(function(slide, i) {
        var editableEls = slide.querySelectorAll('[contenteditable]');
        editableEls.forEach(function(el, j) {
          var key = i + '-' + j;
          if (edits[key]) el.innerHTML = edits[key];
        });
      });
    } catch(e) {}
  }

  loadEdits();

  // Auto-save while editing
  document.addEventListener('input', function() {
    if (editing) {
      clearTimeout(window._saveTimer);
      window._saveTimer = setTimeout(saveEdits, 1000);
    }
  });

  // Hide controls hint after 5s
  setTimeout(function() {
    if (hint) hint.style.opacity = '0';
  }, 5000);

  // Initial reveal for first slide
  slides[0].querySelectorAll('.reveal').forEach(function(el) {
    el.classList.add('visible');
  });
})();
`;
}

/** HTML 转义 */
function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/** JS 字符串转义（用于 <script> 块内嵌字符串，防止脚本注入） */
function escapeJsString(str: string): string {
  return JSON.stringify(str).replace(/</g, '\\u003c');
}

/**
 * @module paper-viz/pdf-figure-extractor
 * @description 使用 Python pymupdf 从 PDF 中提取图表
 *
 * 通过子进程调用 Python 脚本，利用 pymupdf (fitz) 库
 * 提取 PDF 中的图片和图表。提取失败时优雅降级。
 */

import { spawn } from 'child_process';
import { existsSync, mkdirSync, readFileSync } from 'fs';
import { join, basename, dirname } from 'path';
import type { ExtractedFigure } from './types';

/** 图表提取选项 */
export interface FigureExtractorOptions {
  /** 输出图片目录（默认: PDF 同级 figures/ 目录） */
  outputDir?: string;
  /** 最小图片尺寸（宽或高，px），过滤小图标 */
  minSize?: number;
  /** 是否返回 base64 编码（用于内嵌 HTML） */
  embedBase64?: boolean;
  /** Python 可执行文件路径 */
  pythonPath?: string;
}

const DEFAULT_OPTIONS: Required<FigureExtractorOptions> = {
  outputDir: '',
  minSize: 100,
  embedBase64: true,
  pythonPath: 'python',
};

/**
 * PdfFigureExtractor — 从 PDF 提取图表
 *
 * @example
 * ```ts
 * const extractor = new PdfFigureExtractor();
 * const figures = await extractor.extract('/path/to/paper.pdf');
 * ```
 */
export class PdfFigureExtractor {
  private options: Required<FigureExtractorOptions>;

  constructor(options?: FigureExtractorOptions) {
    this.options = { ...DEFAULT_OPTIONS, ...options };
  }

  /**
   * 检测 pymupdf 是否可用
   * @returns 是否已安装
   */
  async checkPymupdf(): Promise<boolean> {
    try {
      const result = await this.runPython(
        'import fitz; print(fitz.version)'
      );
      return result.exitCode === 0;
    } catch {
      return false;
    }
  }

  /**
   * 安装 pymupdf（pip install pymupdf）
   * @returns 是否安装成功
   */
  async installPymupdf(): Promise<boolean> {
    try {
      const result = await this.runCommand(this.options.pythonPath, [
        '-m', 'pip', 'install', 'pymupdf', '--quiet',
      ]);
      return result.exitCode === 0;
    } catch {
      return false;
    }
  }

  /**
   * 从 PDF 文件提取所有图表
   * @param pdfPath - PDF 文件路径
   * @returns 提取的图表列表
   */
  async extract(pdfPath: string): Promise<ExtractedFigure[]> {
    if (!existsSync(pdfPath)) {
      console.error(`PDF file not found: ${pdfPath}`);
      return [];
    }

    // 确保 pymupdf 可用
    const available = await this.checkPymupdf();
    if (!available) {
      console.log('pymupdf not found, attempting to install...');
      const installed = await this.installPymupdf();
      if (!installed) {
        console.error('Failed to install pymupdf. Please run: pip install pymupdf');
        return [];
      }
    }

    // 确定输出目录
    const outputDir = this.options.outputDir || join(dirname(pdfPath), 'figures');
    if (!existsSync(outputDir)) {
      mkdirSync(outputDir, { recursive: true });
    }

    // 构建 Python 提取脚本
    const script = this.buildExtractScript(pdfPath, outputDir);

    try {
      const result = await this.runPython(script);

      if (result.exitCode !== 0) {
        console.error('Figure extraction failed:', result.stderr);
        return [];
      }

      // 解析提取结果 JSON
      const jsonMatch = result.stdout.match(/\[FIGURES_JSON\]([\s\S]*?)\[\/FIGURES_JSON\]/);
      if (!jsonMatch) {
        console.error('Failed to parse extraction results');
        return [];
      }

      const rawFigures: RawFigure[] = JSON.parse(jsonMatch[1]);

      // 转换为 ExtractedFigure 格式
      return rawFigures
        .filter((f) => f.width >= this.options.minSize || f.height >= this.options.minSize)
        .map((f) => this.toExtractedFigure(f));
    } catch (err) {
      console.error('Figure extraction error:', err);
      return [];
    }
  }

  /** 构建 Python 提取脚本 */
  private buildExtractScript(pdfPath: string, outputDir: string): string {
    // 转义路径中的反斜杠
    const safePdfPath = pdfPath.replace(/\\/g, '/');
    const safeOutputDir = outputDir.replace(/\\/g, '/');

    return `
import fitz
import json
import os
import base64

pdf_path = "${safePdfPath}"
output_dir = "${safeOutputDir}"
embed_base64 = ${this.options.embedBase64 ? 'True' : 'False'}

doc = fitz.open(pdf_path)
figures = []
img_index = 0

for page_num in range(len(doc)):
    page = doc[page_num]
    image_list = page.get_images(full=True)

    for img_info in image_list:
        xref = img_info[0]
        try:
            pix = fitz.Pixmap(doc, xref)

            # 转换 CMYK 为 RGB
            if pix.n > 4:
                pix = fitz.Pixmap(fitz.csRGB, pix)

            width = pix.width
            height = pix.height

            # 保存图片
            img_index += 1
            filename = f"figure_{img_index}_p{page_num + 1}.png"
            filepath = os.path.join(output_dir, filename)
            pix.save(filepath)

            # 可选 base64 编码
            b64_data = ""
            if embed_base64:
                with open(filepath, "rb") as f:
                    b64_data = base64.b64encode(f.read()).decode("utf-8")

            figures.append({
                "path": filepath.replace("\\\\", "/"),
                "base64": b64_data,
                "mimeType": "image/png",
                "caption": f"Figure {img_index} (Page {page_num + 1})",
                "pageNumber": page_num + 1,
                "width": width,
                "height": height
            })

            pix = None
        except Exception as e:
            pass

doc.close()

# 尝试从文本中提取图表标题
doc2 = fitz.open(pdf_path)
for fig in figures:
    page = doc2[fig["pageNumber"] - 1]
    text = page.get_text()
    lines = text.split("\\n")
    for line in lines:
        line_stripped = line.strip()
        if line_stripped.lower().startswith(("figure", "fig.", "fig ")):
            # 匹配包含图片编号的标题
            fig_num = figures.index(fig) + 1
            if str(fig_num) in line_stripped[:20]:
                fig["caption"] = line_stripped
                break
doc2.close()

print("[FIGURES_JSON]")
print(json.dumps(figures, ensure_ascii=False))
print("[/FIGURES_JSON]")
`;
  }

  /** 将原始提取结果转为 ExtractedFigure */
  private toExtractedFigure(raw: RawFigure): ExtractedFigure {
    return {
      path: raw.path,
      base64: raw.base64 || undefined,
      mimeType: raw.mimeType,
      caption: raw.caption,
      pageNumber: raw.pageNumber,
      width: raw.width,
      height: raw.height,
    };
  }

  /** 执行 Python 代码 */
  private runPython(code: string): Promise<ProcessResult> {
    return this.runCommand(this.options.pythonPath, ['-c', code]);
  }

  /** 执行子进程命令 */
  private runCommand(cmd: string, args: string[]): Promise<ProcessResult> {
    return new Promise((resolve, reject) => {
      const proc = spawn(cmd, args, {
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 120_000,
      });

      let stdout = '';
      let stderr = '';

      proc.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      proc.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      proc.on('close', (code) => {
        resolve({ exitCode: code ?? 1, stdout, stderr });
      });

      proc.on('error', (err) => {
        reject(err);
      });
    });
  }
}

/** Python 脚本返回的原始图表数据 */
interface RawFigure {
  path: string;
  base64: string;
  mimeType: string;
  caption: string;
  pageNumber: number;
  width: number;
  height: number;
}

/** 子进程执行结果 */
interface ProcessResult {
  exitCode: number;
  stdout: string;
  stderr: string;
}

/**
 * @module paper-viz/ppt-exporter
 * @description 通过 Python python-pptx 子进程导出 PPT 文件
 *
 * 将 PresentationData 序列化为 JSON，传递给内联 Python 脚本，
 * 由 python-pptx 生成 .pptx 文件。
 */

import { spawn } from 'child_process';
import { writeFileSync, unlinkSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { tmpdir } from 'os';
import type { PresentationData, PptExportOptions } from './types';

/** PPT 导出器 */
export class PptExporter {
  private pythonPath: string;

  constructor(pythonPath = 'python') {
    this.pythonPath = pythonPath;
  }

  /**
   * 检测 python-pptx 是否可用
   * @returns 是否已安装
   */
  async checkPptx(): Promise<boolean> {
    try {
      const result = await this.runCommand(this.pythonPath, [
        '-c', 'import pptx; print(pptx.__version__)',
      ]);
      return result.exitCode === 0;
    } catch {
      return false;
    }
  }

  /**
   * 安装 python-pptx
   * @returns 是否安装成功
   */
  async installPptx(): Promise<boolean> {
    try {
      const result = await this.runCommand(this.pythonPath, [
        '-m', 'pip', 'install', 'python-pptx', '--quiet',
      ]);
      return result.exitCode === 0;
    } catch {
      return false;
    }
  }

  /**
   * 导出 PresentationData 为 .pptx 文件
   * @param data - 演示文稿数据
   * @param options - 导出选项
   * @returns 输出文件路径
   */
  async export(data: PresentationData, options: PptExportOptions): Promise<string> {
    // 检测 python-pptx
    const available = await this.checkPptx();
    if (!available) {
      console.log('python-pptx not found, attempting to install...');
      const installed = await this.installPptx();
      if (!installed) {
        throw new Error('Failed to install python-pptx. Please run: pip install python-pptx');
      }
    }

    // 将数据序列化为临时 JSON
    const tempJsonPath = join(tmpdir(), `paper-viz-${Date.now()}.json`).replace(/\\/g, '/');
    const outputPath = options.outputPath.replace(/\\/g, '/');

    try {
      writeFileSync(tempJsonPath, JSON.stringify(this.serializeForPython(data)));

      const script = this.buildPythonScript(tempJsonPath, outputPath, options);
      const result = await this.runPython(script);

      if (result.exitCode !== 0) {
        throw new Error(`PPT export failed: ${result.stderr}`);
      }

      console.log(`PPT exported: ${options.outputPath}`);
      return options.outputPath;
    } finally {
      // 清理临时文件
      try {
        if (existsSync(tempJsonPath)) unlinkSync(tempJsonPath);
      } catch {}
    }
  }

  /** 序列化数据为 Python 友好格式 */
  private serializeForPython(data: PresentationData): PptSerializedData {
    return {
      title: data.title,
      authors: data.authors,
      date: data.date,
      url: data.url,
      theme: {
        primaryColor: data.theme.primaryColor,
        accentColor: data.theme.accentColor,
        backgroundColor: data.theme.backgroundColor,
        textColor: data.theme.textColor,
      },
      slides: data.slides.map((s) => ({
        type: s.type,
        title: s.title,
        subtitle: s.subtitle ?? '',
        layout: s.layout ?? 'default',
        blocks: s.blocks.map((b) => ({
          type: b.type,
          content: b.content,
          items: b.items ?? [],
          caption: b.caption ?? '',
          variant: b.variant ?? '',
        })),
        notes: s.notes ?? '',
      })),
    };
  }

  /** 构建 Python PPT 生成脚本 */
  private buildPythonScript(jsonPath: string, outputPath: string, options: PptExportOptions): string {
    const width = options.width ?? 13.333;
    const height = options.height ?? 7.5;
    const includeNotes = options.includeNotes !== false;

    return `
import json
from pptx import Presentation
from pptx.util import Inches, Pt, Emu
from pptx.dml.color import RGBColor
from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
import os

with open("${jsonPath}", "r", encoding="utf-8") as f:
    data = json.load(f)

prs = Presentation()
prs.slide_width = Inches(${width})
prs.slide_height = Inches(${height})

def hex_to_rgb(hex_str):
    hex_str = hex_str.lstrip('#')
    return RGBColor(int(hex_str[0:2],16), int(hex_str[2:4],16), int(hex_str[4:6],16))

theme = data["theme"]
primary = hex_to_rgb(theme["primaryColor"])
accent = hex_to_rgb(theme["accentColor"])
bg_color = hex_to_rgb(theme["backgroundColor"])
text_color = hex_to_rgb(theme["textColor"])

def set_slide_bg(slide, color):
    bg = slide.background
    fill = bg.fill
    fill.solid()
    fill.fore_color.rgb = color

def add_text_box(slide, left, top, width, height, text, font_size=18, color=None, bold=False, alignment=PP_ALIGN.LEFT):
    txBox = slide.shapes.add_textbox(Inches(left), Inches(top), Inches(width), Inches(height))
    tf = txBox.text_frame
    tf.word_wrap = True
    p = tf.paragraphs[0]
    p.text = text
    p.font.size = Pt(font_size)
    p.font.color.rgb = color or text_color
    p.font.bold = bold
    p.alignment = alignment
    return txBox

for slide_data in data["slides"]:
    slide_layout = prs.slide_layouts[6]  # Blank layout
    slide = prs.slides.add_slide(slide_layout)
    set_slide_bg(slide, bg_color)

    slide_type = slide_data["type"]
    title = slide_data["title"]
    blocks = slide_data["blocks"]

    if slide_type == "title":
        # Title slide - centered
        y = 1.5
        for block in blocks:
            if block["type"] == "heading":
                add_text_box(slide, 1, y, 11.3, 1.5, block["content"],
                           font_size=36, color=primary, bold=True, alignment=PP_ALIGN.CENTER)
                y += 1.8
            elif block["type"] == "text":
                fs = 20 if "authors" in block.get("content","").lower() or len(block["content"]) < 80 else 14
                add_text_box(slide, 1, y, 11.3, 0.8, block["content"],
                           font_size=fs, color=accent if y < 4 else text_color, alignment=PP_ALIGN.CENTER)
                y += 0.9
            elif block["type"] == "list":
                items_text = " | ".join(block.get("items", []))
                add_text_box(slide, 1.5, y, 10.3, 0.6, items_text,
                           font_size=12, alignment=PP_ALIGN.CENTER)
                y += 0.7
    else:
        # Regular slide with title
        add_text_box(slide, 0.8, 0.3, 11.5, 0.8, title,
                   font_size=28, color=primary, bold=True)

        y = 1.4
        for block in blocks:
            if y > 6.8:
                break

            if block["type"] == "text":
                text = block["content"].replace("**", "")
                h = max(0.6, min(2.0, len(text) / 120 * 0.6))
                add_text_box(slide, 0.8, y, 11.5, h, text, font_size=16)
                y += h + 0.2

            elif block["type"] == "quote":
                add_text_box(slide, 1.2, y, 11, 1.2, block["content"],
                           font_size=14, color=accent)
                y += 1.4

            elif block["type"] == "list":
                if block["content"]:
                    add_text_box(slide, 0.8, y, 11.5, 0.4, block["content"],
                               font_size=16, color=primary, bold=True)
                    y += 0.45
                for item in block.get("items", []):
                    if y > 6.8:
                        break
                    add_text_box(slide, 1.2, y, 11, 0.4, "• " + item, font_size=14)
                    y += 0.38

    # Speaker notes
    ${includeNotes ? `
    if slide_data.get("notes"):
        notes_slide = slide.notes_slide
        notes_slide.notes_text_frame.text = slide_data["notes"]
    ` : ''}

output_dir = os.path.dirname("${outputPath}")
if output_dir and not os.path.exists(output_dir):
    os.makedirs(output_dir, exist_ok=True)

prs.save("${outputPath}")
print("OK")
`;
  }

  /** 执行 Python 代码 */
  private runPython(code: string): Promise<ProcessResult> {
    return this.runCommand(this.pythonPath, ['-c', code]);
  }

  /** 执行子进程命令 */
  private runCommand(cmd: string, args: string[]): Promise<ProcessResult> {
    return new Promise((resolve, reject) => {
      const proc = spawn(cmd, args, {
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 60_000,
      });

      let stdout = '';
      let stderr = '';

      proc.stdout.on('data', (d) => { stdout += d.toString(); });
      proc.stderr.on('data', (d) => { stderr += d.toString(); });
      proc.on('close', (code) => resolve({ exitCode: code ?? 1, stdout, stderr }));
      proc.on('error', (err) => reject(err));
    });
  }
}

/** Python 序列化数据格式 */
interface PptSerializedData {
  title: string;
  authors: string[];
  date: string;
  url: string;
  theme: {
    primaryColor: string;
    accentColor: string;
    backgroundColor: string;
    textColor: string;
  };
  slides: Array<{
    type: string;
    title: string;
    subtitle: string;
    layout: string;
    blocks: Array<{
      type: string;
      content: string;
      items: string[];
      caption: string;
      variant: string;
    }>;
    notes: string;
  }>;
}

/** 子进程执行结果 */
interface ProcessResult {
  exitCode: number;
  stdout: string;
  stderr: string;
}

/**
 * @module paper-viz/slide-builder
 * @description 将 PaperAnalysis 转换为 PresentationData 幻灯片数据
 */

import type { PaperAnalysis, KeyPoint, Contribution } from '../../paper-analyzer/scripts/types';
import type {
  PresentationData,
  PresentationSlide,
  ContentBlock,
  ExtractedFigure,
  PresentationTheme,
} from './types';
import { ACADEMIC_DARK_THEME } from './types';

/** SlideBuilder 配置选项 */
export interface SlideBuilderOptions {
  /** 使用的主题 */
  theme?: PresentationTheme;
  /** 每页关键要点最大数量 */
  maxPointsPerSlide?: number;
  /** 每页实验结果最大数量 */
  maxExperimentsPerSlide?: number;
  /** 是否包含参考文献页 */
  includeReferences?: boolean;
  /** 已提取的图表列表 */
  figures?: ExtractedFigure[];
}

const DEFAULT_OPTIONS: Required<SlideBuilderOptions> = {
  theme: ACADEMIC_DARK_THEME,
  maxPointsPerSlide: 4,
  maxExperimentsPerSlide: 3,
  includeReferences: true,
  figures: [],
};

/**
 * SlideBuilder — 将论文分析结果转换为演示文稿数据
 *
 * @example
 * ```ts
 * const builder = new SlideBuilder();
 * const presentation = builder.buildFromAnalysis(analysis);
 * ```
 */
export class SlideBuilder {
  private options: Required<SlideBuilderOptions>;
  private slideCounter = 0;

  constructor(options?: SlideBuilderOptions) {
    this.options = { ...DEFAULT_OPTIONS, ...options };
  }

  /**
   * 从 PaperAnalysis 构建完整的演示文稿数据
   * @param analysis - 论文分析结果
   * @returns 演示文稿数据
   */
  buildFromAnalysis(analysis: PaperAnalysis): PresentationData {
    this.slideCounter = 0;

    const slides: PresentationSlide[] = [
      this.buildTitleSlide(analysis),
      this.buildAbstractSlide(analysis),
      ...this.buildKeyPointsSlides(analysis.keyPoints),
      this.buildMethodologySlide(analysis),
      ...this.buildExperimentsSlides(analysis),
      this.buildContributionsSlide(analysis.contributions),
      this.buildLimitationsSlide(analysis),
    ];

    if (this.options.includeReferences && analysis.relatedWork.length > 0) {
      slides.push(this.buildReferencesSlide(analysis));
    }

    return {
      title: analysis.metadata.title,
      authors: analysis.metadata.authors,
      date: analysis.metadata.year,
      url: analysis.metadata.url,
      slides,
      figures: this.options.figures,
      theme: this.options.theme,
      generatedAt: new Date().toISOString(),
    };
  }

  /** 生成唯一幻灯片 ID */
  private nextId(prefix: string): string {
    return `${prefix}-${++this.slideCounter}`;
  }

  /** 标题页 */
  private buildTitleSlide(analysis: PaperAnalysis): PresentationSlide {
    const blocks: ContentBlock[] = [
      { type: 'heading', content: analysis.metadata.title },
    ];

    if (analysis.metadata.authors.length > 0) {
      blocks.push({
        type: 'text',
        content: analysis.metadata.authors.join(', '),
        className: 'authors',
      });
    }

    const metaItems: string[] = [];
    if (analysis.metadata.venue) metaItems.push(analysis.metadata.venue);
    if (analysis.metadata.year) metaItems.push(analysis.metadata.year);
    if (analysis.metadata.doi) metaItems.push(`DOI: ${analysis.metadata.doi}`);

    if (metaItems.length > 0) {
      blocks.push({
        type: 'text',
        content: metaItems.join(' · '),
        className: 'meta',
      });
    }

    if (analysis.metadata.keywords.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Keywords',
        items: analysis.metadata.keywords,
        className: 'keywords',
      });
    }

    return {
      id: this.nextId('title'),
      type: 'title',
      title: analysis.metadata.title,
      blocks,
      layout: 'center',
      notes: `Paper URL: ${analysis.metadata.url}`,
    };
  }

  /** 摘要页 */
  private buildAbstractSlide(analysis: PaperAnalysis): PresentationSlide {
    const blocks: ContentBlock[] = [];

    if (analysis.summary) {
      blocks.push({
        type: 'text',
        content: analysis.summary,
        className: 'summary',
      });
    }

    if (analysis.abstract) {
      blocks.push({
        type: 'quote',
        content: analysis.abstract,
      });
    }

    return {
      id: this.nextId('abstract'),
      type: 'abstract',
      title: 'Abstract & Summary',
      blocks,
      layout: 'default',
    };
  }

  /** 关键要点页（可能拆分为多页） */
  private buildKeyPointsSlides(keyPoints: KeyPoint[]): PresentationSlide[] {
    if (keyPoints.length === 0) {
      return [
        {
          id: this.nextId('keypoints'),
          type: 'key-points',
          title: 'Key Points',
          blocks: [{ type: 'text', content: 'No key points extracted.' }],
          layout: 'default',
        },
      ];
    }

    const max = this.options.maxPointsPerSlide;
    const chunks = this.chunk(keyPoints, max);

    return chunks.map((chunk, i) => {
      const blocks: ContentBlock[] = chunk.map((kp) => ({
        type: 'list' as const,
        content: kp.point,
        items: [kp.explanation],
        variant: kp.importance as ContentBlock['variant'],
        className: `importance-${kp.importance}`,
      }));

      const suffix = chunks.length > 1 ? ` (${i + 1}/${chunks.length})` : '';

      return {
        id: this.nextId('keypoints'),
        type: 'key-points' as const,
        title: `Key Points${suffix}`,
        blocks,
        layout: 'default' as const,
      };
    });
  }

  /** 方法论页 */
  private buildMethodologySlide(analysis: PaperAnalysis): PresentationSlide {
    const m = analysis.methodology;
    const blocks: ContentBlock[] = [];

    if (m.overview) {
      blocks.push({ type: 'text', content: m.overview });
    }

    if (m.approach) {
      blocks.push({
        type: 'text',
        content: `**Approach:** ${m.approach}`,
        className: 'approach',
      });
    }

    if (m.novelty) {
      blocks.push({
        type: 'quote',
        content: `Novelty: ${m.novelty}`,
      });
    }

    if (m.strengths.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Strengths',
        items: m.strengths,
        className: 'strengths',
      });
    }

    if (m.weaknesses.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Weaknesses',
        items: m.weaknesses,
        className: 'weaknesses',
      });
    }

    return {
      id: this.nextId('methodology'),
      type: 'methodology',
      title: 'Methodology',
      blocks,
      layout: 'default',
    };
  }

  /** 实验结果页（可能拆分为多页，含图表） */
  private buildExperimentsSlides(analysis: PaperAnalysis): PresentationSlide[] {
    const exp = analysis.experiments;
    const slides: PresentationSlide[] = [];
    const blocks: ContentBlock[] = [];

    if (exp.mainResults) {
      blocks.push({ type: 'text', content: exp.mainResults });
    }

    if (exp.datasets.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Datasets',
        items: exp.datasets,
      });
    }

    if (exp.metrics.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Metrics',
        items: exp.metrics,
      });
    }

    if (exp.baselines.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Baselines',
        items: exp.baselines,
      });
    }

    slides.push({
      id: this.nextId('experiments'),
      type: 'experiments',
      title: 'Experiments & Results',
      blocks,
      layout: 'default',
    });

    // 图表幻灯片
    const figures = this.options.figures;
    if (figures.length > 0) {
      const figChunks = this.chunk(figures, 2);
      for (const chunk of figChunks) {
        const figBlocks: ContentBlock[] = chunk.map((fig) => ({
          type: 'image' as const,
          content: fig.caption || 'Figure',
          src: fig.base64
            ? `data:${fig.mimeType};base64,${fig.base64}`
            : fig.path,
          caption: fig.caption,
        }));

        slides.push({
          id: this.nextId('experiments'),
          type: 'experiments',
          title: 'Figures',
          blocks: figBlocks,
          layout: figBlocks.length === 1 ? 'full-image' : 'two-column',
        });
      }
    }

    // 消融实验
    if (exp.ablations.length > 0) {
      slides.push({
        id: this.nextId('experiments'),
        type: 'experiments',
        title: 'Ablation Studies',
        blocks: [
          {
            type: 'list',
            content: 'Ablation Results',
            items: exp.ablations,
          },
          ...(exp.analysis
            ? [{ type: 'text' as const, content: exp.analysis }]
            : []),
        ],
        layout: 'default',
      });
    }

    return slides;
  }

  /** 贡献页 */
  private buildContributionsSlide(contributions: Contribution[]): PresentationSlide {
    const blocks: ContentBlock[] = contributions.map((c) => ({
      type: 'list' as const,
      content: c.description,
      items: [`Type: ${c.type}`, `Significance: ${c.significance}`],
      variant: c.significance as ContentBlock['variant'],
      className: `significance-${c.significance}`,
    }));

    if (blocks.length === 0) {
      blocks.push({ type: 'text', content: 'No explicit contributions listed.' });
    }

    return {
      id: this.nextId('contributions'),
      type: 'contributions',
      title: 'Contributions',
      blocks,
      layout: 'default',
    };
  }

  /** 局限与展望页 */
  private buildLimitationsSlide(analysis: PaperAnalysis): PresentationSlide {
    const blocks: ContentBlock[] = [];

    if (analysis.limitations.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Limitations',
        items: analysis.limitations.map(
          (l) => `[${l.impact.toUpperCase()}] ${l.description}${l.potentialSolution ? ` → ${l.potentialSolution}` : ''}`
        ),
        className: 'limitations',
      });
    }

    if (analysis.futureWork.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Future Work',
        items: analysis.futureWork,
        className: 'future-work',
      });
    }

    if (blocks.length === 0) {
      blocks.push({ type: 'text', content: 'No limitations or future work discussed.' });
    }

    return {
      id: this.nextId('limitations'),
      type: 'limitations',
      title: 'Limitations & Future Work',
      blocks,
      layout: 'default',
    };
  }

  /** 参考文献页 */
  private buildReferencesSlide(analysis: PaperAnalysis): PresentationSlide {
    const blocks: ContentBlock[] = [];

    for (const rw of analysis.relatedWork) {
      blocks.push({
        type: 'list',
        content: rw.category,
        items: [...rw.papers, rw.comparison ? `Comparison: ${rw.comparison}` : ''].filter(Boolean),
      });
    }

    if (analysis.citations.keyReferences.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Key References',
        items: analysis.citations.keyReferences,
      });
    }

    if (analysis.recommendations.furtherReading.length > 0) {
      blocks.push({
        type: 'list',
        content: 'Further Reading',
        items: analysis.recommendations.furtherReading,
      });
    }

    return {
      id: this.nextId('references'),
      type: 'references',
      title: 'Related Work & References',
      blocks,
      layout: 'default',
    };
  }

  /** 数组分块工具 */
  private chunk<T>(arr: T[], size: number): T[][] {
    const result: T[][] = [];
    for (let i = 0; i < arr.length; i += size) {
      result.push(arr.slice(i, i + size));
    }
    return result;
  }
}

/**
 * @module paper-viz/types
 * @description 论文可视化演示的数据类型定义
 */

/** 幻灯片类型 */
export type SlideType =
  | 'title'
  | 'abstract'
  | 'key-points'
  | 'methodology'
  | 'experiments'
  | 'contributions'
  | 'limitations'
  | 'references';

/** 幻灯片内容块 */
export interface ContentBlock {
  /** 块类型 */
  type: 'heading' | 'text' | 'list' | 'quote' | 'image' | 'table' | 'badge';
  /** 文本内容（image 类型时为 alt 文本） */
  content: string;
  /** 列表项（type='list' 时使用） */
  items?: string[];
  /** 图片路径或 base64（type='image' 时使用） */
  src?: string;
  /** 图片标题 */
  caption?: string;
  /** 徽章变体（type='badge' 时使用） */
  variant?: 'critical' | 'important' | 'supporting' | 'major' | 'moderate' | 'minor';
  /** 附加 CSS 类名 */
  className?: string;
}

/** 单张幻灯片 */
export interface PresentationSlide {
  /** 幻灯片唯一 ID */
  id: string;
  /** 幻灯片类型 */
  type: SlideType;
  /** 幻灯片标题 */
  title: string;
  /** 副标题 */
  subtitle?: string;
  /** 内容块列表 */
  blocks: ContentBlock[];
  /** 演讲者备注 */
  notes?: string;
  /** 自定义布局类名 */
  layout?: 'center' | 'two-column' | 'full-image' | 'default';
}

/** 演示主题配置 */
export interface PresentationTheme {
  /** 主题名称 */
  name: string;
  /** 主色调 */
  primaryColor: string;
  /** 强调色 */
  accentColor: string;
  /** 背景色 */
  backgroundColor: string;
  /** 表面色（卡片等） */
  surfaceColor: string;
  /** 文本色 */
  textColor: string;
  /** 次要文本色 */
  textSecondaryColor: string;
  /** 代码/引用背景色 */
  codeBackground: string;
  /** 字体族 */
  fontFamily: string;
  /** 标题字体族 */
  headingFontFamily: string;
}

/** 提取的图表信息 */
export interface ExtractedFigure {
  /** 图片文件路径（相对或绝对） */
  path: string;
  /** base64 编码数据（用于内嵌 HTML） */
  base64?: string;
  /** MIME 类型 */
  mimeType: string;
  /** 图表标题/描述 */
  caption: string;
  /** 在 PDF 中的页码 */
  pageNumber: number;
  /** 图片宽度（px） */
  width: number;
  /** 图片高度（px） */
  height: number;
}

/** 完整演示文稿数据 */
export interface PresentationData {
  /** 演示文稿标题 */
  title: string;
  /** 论文作者列表 */
  authors: string[];
  /** 论文发表日期 */
  date: string;
  /** 论文原文 URL */
  url: string;
  /** 幻灯片列表 */
  slides: PresentationSlide[];
  /** 提取的图表 */
  figures: ExtractedFigure[];
  /** 主题配置 */
  theme: PresentationTheme;
  /** 生成时间 */
  generatedAt: string;
}

/** PPT 导出选项 */
export interface PptExportOptions {
  /** 输出文件路径 */
  outputPath: string;
  /** 幻灯片宽度（英寸） */
  width?: number;
  /** 幻灯片高度（英寸） */
  height?: number;
  /** 是否包含演讲者备注 */
  includeNotes?: boolean;
}

